      bank.forEach((item,id)=>{item.id=id;if(!groups.has(item.group))groups.set(item.group,[]);groups.get(item.group).push(item);});
      ['Marketing','Finance','Hospitality and Tourism','Business Management & Administration','Entrepreneurship'].forEach(category=>{const option=document.createElement('option');option.value=category;option.textContent=category;el('category').appendChild(option);});
      let phase='start',pool=[],deck=[],current,options=[],remaining=60000,started=0,ticker=null,advance=null,pausedFrom='question';
      let score=0,streak=0,maxStreak=0,answered=0,correct=0,missed=[],number=0,category='all';
      const focus=node=>node.focus({preventScroll:true});
